43	/// Validate one chat completion request and proxy it into the shared
44	/// `vllm-chat` stack.
45	pub async fn chat_completions(
46	    State(state): State<Arc<AppState>>,
47	    headers: HeaderMap,
48	    ValidatedJson(body): ValidatedJson<ChatCompletionRequest>,
49	) -> Response {
50	    let stream = body.stream;
51	    let request_context = resolve_request_context(&headers, body.request_id.as_deref());
52	    let lora_resolution = state.resolve_model_with_loras(Some(&body.model)).await;
53	
54	    let prepared = match prepare_chat_request(body, &lora_resolution, request_context) {
55	        Ok(prepared) => prepared,
56	        Err(error) => return error.into_response(),
57	    };
58	    let request_span = tracing::info_span!(
59	        "chat_completions",
60	        request_id = %prepared.request_id,
61	        engine_request_id = tracing::field::Empty,
62	    );
63	
64	    let created = unix_timestamp();
65	    let log_request = state.enable_log_requests;
66	
67	    let chat_stream =
68	        match state.chat.chat(prepared.chat_request).instrument(request_span.clone()).await {
69	            Ok(stream) => stream,
70	            Err(error) => {
71	                return server_error!(
72	                    "failed to submit chat request: {}",
73	                    error.to_report_string()
74	                )
75	                .into_response();
76	            }
77	        };
78	
79	    if stream {
80	        let chunk_stream = chat_completion_chunk_stream(
81	            chat_stream,
82	            prepared.request_id,
83	            prepared.response_model,
84	            created,
85	            log_request,
86	            prepared.include_usage,
87	            prepared.requested_logprobs,
88	            prepared.echo,
89	            prepared.return_token_ids,
90	            prepared.return_tokens_as_token_ids,
91	        );
92	        let sse_stream = chat_completion_sse_stream(chunk_stream).instrument(request_span);
93	
94	        Sse::new(sse_stream).into_response()
95	    } else {
96	        let response = match collect_chat_completion(
97	            chat_stream,
98	            prepared.request_id,
99	            prepared.response_model,
100	            created,
101	            prepared.requested_logprobs,
102	            prepared.include_prompt_logprobs,
103	            prepared.echo,
104	            prepared.return_token_ids,
105	            prepared.return_tokens_as_token_ids,
106	        )
107	        .instrument(request_span.clone())
108	        .await
109	        {
110	            Ok(response) => response,
111	            Err(error) => return error.into_response(),
112	        };
113	
114	        if log_request {
115	            let usage = response.usage.as_ref();
116	            info!(
117	                parent: &request_span,
118	                model = %response.model,
119	                prompt_tokens = usage.map_or(0, |u| u.prompt_tokens),
120	                output_tokens = usage.and_then(|u| u.completion_tokens).unwrap_or(0),
121	                finish_reason = response.choices.first().and_then(|c| c.finish_reason.as_deref()).unwrap_or("unknown"),
122	                "chat completion finished"
123	            );
124	        }
125	
126	        Json(response).into_response()
127	    }
128	}
